#!/usr/bin/env python3
"""At-scale independent check: mask-the-query LPM vs the compiled image."""
import random, socket, struct, subprocess, sys
BIN = '/work/submit/planb64'

def load_fib(path):
    d = {}
    n = 0
    for line in open(path):
        toks = [t for t in line.replace('\t', ' ').replace('\r', ' ').split(' ') if t]
        if not toks: continue
        spec, hop = toks[0], int(toks[1])
        addr, ln = spec.rsplit('/', 1)
        ln = int(ln)
        b = socket.inet_pton(socket.AF_INET6, addr)
        upper = struct.unpack(">Q", b[:8])[0]
        start = 0 if ln == 0 else upper & ((((1 << ln) - 1) << (64 - ln)) & ((1 << 64) - 1))
        assert (start, ln) not in d, "dup"
        d[(start, ln)] = hop
        n += 1
    return d, n

def lpm(d, key):
    for ln in range(64, -1, -1):
        if ln == 0:
            if (0, 0) in d: return (d[(0, 0)], 0)
        else:
            m = key & ((((1 << ln) - 1) << (64 - ln)) & ((1 << 64) - 1))
            if (m, ln) in d: return (d[(m, ln)], ln)
    return (-1, -1)

rng = random.Random(4242)
for fibname in ('fib_max.txt', 'fib_mix.txt', 'fib_top.txt'):
    d, n = load_fib(fibname)
    img = fibname.replace('.txt', '.idx')
    rows = sum(1 for i, _ in enumerate(open(img)) if i >= 2)
    # queries: random keys + keys derived from the FIB prefixes (starts, ends, +-1)
    keys = [rng.getrandbits(64) for _ in range(700)]
    for (s, ln) in list(d.keys())[:150]:
        for off in (0, 1, (1 << (64 - ln)) - 1 if ln < 64 else 0, (1 << (64 - ln)) if ln < 64 else 0):
            keys.append((s + off) & ((1 << 64) - 1))
    with open('big_trace.txt', 'w') as f:
        for k in keys:
            w = [(k>>48)&0xffff,(k>>32)&0xffff,(k>>16)&0xffff,k&0xffff,0,0,0,0]
            f.write(":".join("%x" % x for x in w) + "\n")
    want = "".join("%d %d\n" % lpm(d, k) for k in keys)
    for mode in ('scalar', 'batch 256'):
        p = subprocess.run([BIN, 'lookup', img, 'big_trace.txt'] + mode.split(), capture_output=True)
        assert p.returncode == 0, p.stderr
        if p.stdout.decode() != want:
            ga, wa = p.stdout.decode().splitlines(), want.splitlines()
            for i, (a, b) in enumerate(zip(ga, wa)):
                if a != b:
                    print("MISMATCH", fibname, mode, "line", i, "key", hex(keys[i]), "got", a, "want", b); sys.exit(1)
    print("%s: fib=%d rows=%d queries=%d OK" % (fibname, n, rows, len(keys)))
print("AT-SCALE CHECK OK")
PYEOF
